'From Squeak6.0 of 8 June 2026 [latest update: #22156] on 14 July 2026 at 3:07:37 pm'!!PreferenceBrowserMorph methodsFor: 'submorphs - search panel' stamp: 'MU 7/14/2026 15:07'!newSearchTextField		| ptm  |	ptm := PluggableTextMorphPlus		on: self model		text: #searchPatternNeverTriggered		accept: #searchPattern:.		ptm		name: #search;		minimumHeight: 0;		balloonText: 'Search preferences ...' translated;		hideScrollBarsIndefinitely;		vResizing: #spaceFill;		hResizing: #spaceFill;		acceptOnCR: true;		onKeyStrokeSend: #value to: [ ptm hasUnacceptedEdits ifTrue: [ ptm accept ] ].	^ptm.! !